[data-bz-node="s3t1"][data-bz-node] p{font-family:Inter, sans-serif;font-size:18px;font-weight:700;font-style:normal;line-height:28.8px;letter-spacing:normal;text-transform:none;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:40px;margin-left:0px;max-width:960px}
