[data-bz-node^="s3b4-r"][data-bz-node] .bz-btn:focus{outline: rgb(20, 21, 26) solid 3px; outline-offset: 3px}
[data-bz-node^="s3b4-r"][data-bz-node] .bz-btns{margin:0;gap:0}
